from pathlib import Path
import hashlib, json, sqlite3, xml.etree.ElementTree as E

H=Path(__file__).resolve().parent
B=H.parents[1]
original=json.loads((B/'runtime/sru-integral/original-articles.json').read_text())
canonical=json.loads((H/'full-law-canonical-evidence.json').read_text())
external=json.loads((H/'full-law-outside-evidence.json').read_text())['articles']
db=sqlite3.connect('file:'+str(B/'corpus.sqlite')+'?mode=ro',uri=True)
db.row_factory=sqlite3.Row
for num in ('L443-15-1-1',):
    a=dict(db.execute('SELECT * FROM articles WHERE code_id=? AND number=? AND valid_from<=? AND valid_until>?',('LEGITEXT000006074096',num,'2026-10-18','2026-10-18')).fetchone())
    doc=db.execute("SELECT xml FROM documents WHERE code_id=? AND id=? AND kind='ARTICLE'",(a['code_id'],a['id'])).fetchone()[0]
    raw=doc.decode()if isinstance(doc,bytes)else doc
    node=E.fromstring(raw);note=node.find('NOTA/CONTENU')
    a.update(whole_article_xml=raw,source_notes_xml=E.tostring(note,encoding='unicode')if note is not None else'',source_url='https://www.legifrance.gouv.fr/codes/article_lc/'+a['id'])
    if not any(x['id']==a['id']for x in canonical):canonical.append(a)
(H/'full-law-canonical-evidence.json').write_text(json.dumps(canonical,ensure_ascii=False,indent=2)+'\n')

entries=[]
def refs(*numbers):
    out=[]
    for num in numbers:
        found=[a for a in canonical+external if a['number']==num and a['valid_from']<='2026-10-18'<a['valid_until']]
        for a in found:
            ident=a.get('source_id')or a.get('id')
            out.append({'number':num,'owner':a.get('owner')or a.get('code_id'),'source_id':ident,'valid_from':a['valid_from'],'valid_until':a['valid_until'],'source_sha256':a['source_sha256'],'source_url':a['source_url']})
    return out
def add(num,status,description,current=(),parts=None,action=None,limits=None):
    a=next(x for x in original if x['number']==str(num))
    entries.append({'sru_article':str(num),'original_text':a['text'],'original_source_url':a['source_url'],'original_text_sha256':hashlib.sha256(a['text'].encode()).hexdigest(),'original_read_complete':True,'status':status,'lineage':description,'current_references':refs(*current),'components':parts or[],'drafting_action':action or'Cartographie seulement ; aucune nouvelle proposition comptée comme réécriture.','limits':limits or[]})

add(56,'replaced_with_quota_descendant',
    'La phrase ajoutée en 2000 à L302-4 a été remplacée lors des refontes du PLH. Le II actuel, depuis 2017, impose une modification dans les deux ans au titre des nouvelles obligations L302-5 et suivants, avec contrôle préfectoral et réaffectation du prélèvement : descendant opératoire du même objet, déjà traité dans le lot quotas du parent.',('L302-4',),action='Rattacher au candidat L302-4 du lot quotas ; ne pas réécrire une deuxième fois la version de 2000.')
add(57,'repealed_no_active_clause',
    'La majoration de l’attribution de compensation proportionnelle à la contribution L302-8 est présente dans les versions 2000–2013 de 1609 nonies C, puis supprimée à compter du 20 janvier 2013 par l’article 25 de la loi 2013-61. Elle ne figure plus dans le V actuel. La compétence fiscale intercommunale et les autres majorations ne sont pas créées par SRU 57.',('1609 nonies C',),action='Aucun nouveau retrait dans 1609 nonies C au titre de 57 ; aucune remise en vigueur de l’ancien calcul.',limits=['Les autres références historiques de 1609 nonies C ne sont pas assimilées à ce mécanisme disparu.'])
add(58,'active_literal_descendant',
    'La participation des maires d’arrondissement de Paris, Marseille et Lyon subsiste au deuxième alinéa du I de L302-1, après les refontes du reste du PLH.',('L302-1',),action='Candidat intégral prêt dans collectivites-candidates/001 : retrait de la seule participation obligatoire, transition des consultations/programmes valablement engagés, autres règles conservées.')
add(59,'active_literal_descendant',
    'La phrase « Il fixe les conditions dans lesquelles ces conventions de réservation sont conclues, en contrepartie d’un apport de terrain, d’un financement ou d’une garantie financière, accordés par une commune ou un EPCI » subsiste dans L441-1. La phrase suivante sur prolongation cinq ans résulte d’un apport postérieur et n’est pas, à elle seule, SRU 59.',('L441-1',),action='Cible précise : première phrase du paragraphe des conventions territoriales de réservation ; conserver l’encadrement général antérieur du décret et distinguer la prolongation postérieure. Pas d’abrogation de tout L441-1.')
add(60,'repealed_number_reused',
    'L’ajout des représentants EPCI à la conférence intercommunale figurait dans L441-1-4 version 2000 puis 2004. L’article 70 de la loi 2006-872 a remplacé ce mécanisme en juillet 2006. L441-1-4 actuel fixe des délais de saisine de la médiation logement et des consultations nouvelles : identité de numéro sans identité de norme.',('L441-1-4',),action='Ne pas abroger L441-1-4 actuel au titre de SRU 60. L’ancienne conférence et sa composition ne sont plus une obligation opératoire autonome.',limits=['Les conférences de logement ultérieurement créées ont leurs propres bases ; une ressemblance fonctionnelle ne prouve pas une descendance de la seule insertion de 2000.'])
add(61,'recodified_active_benefit',
    'L’élargissement des bailleurs de la catégorie APL, auparavant sociétés d’économie mixte, aux bailleurs du quatrième alinéa de l’article 41 ter de la loi 1986-1290 subsiste. L351-2 a été abrogé au 1er septembre 2019 par ordonnance 2019-770 article 2 ; son 2° a été repris dans L831-1 2°.',('L831-1',),action='Cible recodifiée L831-1 2°, et non L351-2 abrogé. Distinguer la chaîne d’éligibilité APL des obligations administratives : supprimer cet élargissement réduirait une aide au logement et nécessite une décision explicite du parent sur sa préservation autonome.',limits=['Aucun rétablissement silencieux de l’ancien champ restreint des bénéficiaires et aucun retrait rétroactif des droits APL déjà constitués.'])
add(62,'active_created_articles',
    'SRU 62 a créé CGCT L1523-5 (subventions, avances, cessions de terrains/constructions aux SEM logement) et L1523-6 (subventions exceptionnelles de redressement). Ces deux habilitations demeurent, avec conditions conventionnelles, financières et rapports. L1523-5 a ensuite perdu, à compter de l’exercice 2010, la mention du tableau de cessions, sans perdre le reste de sa base.',('L1523-5','L1523-6'),parts=[{'part':'L1523-5 validation de conventions antérieures','status':'historical_validation_effects','note':'Validation d’actes antérieurs sous réserve des décisions définitives : ne pas annuler rétroactivement ces actes.'},{'part':'L1523-6','status':'active','note':'Rapport spécial, commissaire aux comptes et information annuelle rattachés à l’aide exceptionnelle.'}],action='Compagnons CGCT à rédiger sur ces deux normes créées, avec transition des financements/conventions et des dettes antérieurs ; coordonner aussi L1525-3.')
add(63,'active_coordination_clause',
    'La réserve « à l’exception des articles L1523-5 et L1523-6 » subsiste au 3° de CGCT L1525-3 pour certaines SEM outre-mer. Elle étend ces deux aides à des sociétés normalement exclues du titre.',('L1525-3',),action='Si L1523-5/6 sont abrogés, retirer uniquement cette exception et conserver les autres exclusions du titre. Ne pas généraliser l’application du titre aux sociétés jusque-là exclues.')
add(64,'mixed_active_and_consumed_transition',
    'Les cinq modifications codifiées et les règles transitoires doivent être suivies séparément. Les compétences habitat des EPCI existaient partiellement avant 2000 ; SRU n’en a pas créé la totalité.',('L2254-1','L5216-5','L5214-16','L5215-20'),parts=[
        {'part':'I 1°','status':'active_created_article','target':'L2254-1','note':'Obligation communale/intercommunale de permettre la réalisation des logements sociaux par interventions foncières, aménagements ou subventions, inchangée depuis 2000.'},
        {'part':'I 2°','status':'active_partial_replacement','target':'L5216-5 I3°','note':'Ajouts identifiés : actions/aides financières sociales et réserves foncières. PLH, politique du logement, logement des personnes défavorisées et amélioration du parc figuraient déjà dans le groupe de 1999 ; ne pas abroger tout I3°.'},
        {'part':'I 3°','status':'active_created_subdivision','target':'L5216-5 II bis','note':'Droit de préemption communautaire pour équilibre social de l’habitat après délibérations concordantes, toujours présent.'},
        {'part':'I 4°','status':'active_created_subdivision','target':'L5214-16 VI','note':'Même faculté de préemption sous compétence habitat de la communauté de communes, toujours présente dans la version 2025.'},
        {'part':'I 5°','status':'active_rewritten_descendant','target':'L5215-20 I3°b','note':'Remplacement de « politique du logement social » par aides financières/actions. Les limites d’intérêt communautaire de 2000 ont été retirées ensuite ; ne pas enlever la politique du logement et les autres compétences préexistantes.'},
        {'part':'II','status':'consumed_creation_transfer_procedures','note':'Application aux EPCI existants/en constitution en 2000, suspensions de transformations jusqu’au transfert de compétences et exception de grands districts : procédures historiques consommées, pas motif de défaire les créations/transferts achevés.'}],action='Rédiger séparément les véritables ajouts et leurs transitions de compétence, contrats, biens et personnels ; ne pas présenter la suppression de toute la compétence habitat des EPCI comme une simple abrogation de SRU.')
add(65,'active_scope_expansion',
    'L’introduction de L431-4 permet depuis SRU aux régions et aux EPCI, en plus des départements/communes, les concours aux organismes HLM. La même version 2000 reste applicable.',('L431-4',),action='Retirer le seul élargissement d’acteurs s’il est confirmé par le parent, sans abroger les pouvoirs antérieurs des départements/communes ni les contrats valablement engagés. Attention : il s’agit d’une faculté de financement, pas d’une nouvelle taxe.')
add(66,'active_definition_reference',
    'Les mots « visés à l’article L411-2 » ajoutés au 1° de L431-4 restent présents. Il s’agit d’un renvoi définissant les organismes HLM, pas d’un prélèvement ou d’une obligation autonome de financement.',('L431-4',),action='Coordination avec 65 sur l’article entier ; éviter de modifier involontairement les catégories de bénéficiaires en supprimant seulement une définition utile.')
add(67,'transferred_active_permission',
    'La faculté de mise à disposition de locaux associatifs créée dans L443-11 a été déplacée par ELAN 2018 article 97 à L443-15-1-1. Elle est la deuxième phrase du premier alinéa actuel ; les autres phrases traitent d’autres facultés de location.',('L443-15-1-1',),action='Retrait ciblé de cette deuxième phrase ; ne pas supprimer tout le L443-11 actuel ni les autres facultés de L443-15-1-1. Les conventions et droits existants nécessitent une transition.')
add(68,'arbitrated_prospective_tax_franchise_removal',
    'La franchise de taxe commerciale de 10 000 francs créée en ZUS est devenue une franchise TASCOM de 1 500 euros dans les QPV, à l’article 3 de la loi 72-657. Elle demeure au sixième paragraphe actuel.',('3',),action='Arbitrage exprès du parent selon la demande plus récente « Toute la loi SRU » : retrait prospectif de la franchise, effet d’augmentation pour ses anciens bénéficiaires explicité, aucun changement de taux ni hausse nationale chiffrée. Candidat entier dans collectivites-companions/002/manifest.json ; faits générateurs antérieurs protégés.',limits=['Le propriétaire de la référence numéro 3 est la loi 72-657, pas le CGI.'])
add(69,'active_created_permission',
    'L424-2 est créé en entier par SRU 69. La loi 2018-1021 article 88 a élargi le champ territorial de la même habilitation, sans créer une autre règle indépendante dans cet article.',('L424-2',),action='Candidat intégral et deux coordinations prêts dans collectivites-candidates/001 : L424-2, R*442-3-3 et Annexe R422-1 28°. Le zonage des autres dispositifs reste conservé.')
add(70,'partly_censored_partly_active',
    'Les 1° et 2° sont déclarés non conformes dans la version promulguée (décision 2000-436 DC) : aucune norme ainsi censurée à abroger ou à réintroduire. Le 3° ajoute au second alinéa I de L510-1 le critère spécifique logement social/mixité, toujours présent.',('L510-1',),parts=[{'part':'1°','status':'censored_before_promulgation'},{'part':'2°','status':'censored_before_promulgation'},{'part':'3°','status':'active_literal_descendant'}],action='Seul 3° fait l’objet du candidat L510-1 dans 001 ; régime d’agrément et autres critères antérieurs conservés.')
add(71,'repealed_number_reused',
    'L’ajout des associations de locataires à l’ancienne conférence régionale francilienne figurait dans L441-1-6 version 2000–2006. La loi 2006-872 article 70 l’a abrogé au 16 juillet 2006. Le numéro est recréé en 2017 pour une convention intercommunale d’attribution, avec une autre norme.',('L441-1-6',),action='Aucune abrogation du L441-1-6 actuel au seul titre de SRU 71 ; ne pas confondre réutilisation du numéro et survie de l’ancienne conférence.')
add(86,'mixed_repealed_and_historical_cohorts',
    'I : la date de délimitation réputée au 1er janvier 1997 de CGI 44 octies est devenue sans support courant après abrogation de 44 octies au 1er janvier 2022 (loi 2021-1900 article 35). II : le V de la loi 96-987 article 12 conserve littéralement la période initiale et le point de départ d’embauche de 1997 ; III : le I de son article 14 garde la correction de date initiale. Les dispositifs ultérieurs ont leurs propres cohortes et sorties dégressives.',('12','14'),parts=[{'part':'I','status':'support_repealed_2022','target':'CGI44octies'},{'part':'II','status':'literal_1997_cohort_consumed','target':'loi96-987article12V'},{'part':'III','status':'literal_1997_cohort_consumed','target':'loi96-987article14I'}],action='Ne pas supprimer toutes les exonérations ZFU au prétexte des corrections de date SRU. Les cohortes 2003/2004/2006 ouvertes jusqu’à fin 2014 et certaines embauches ultérieures ont des règles propres avec durée dégressive pouvant encore produire effet ; préserver droits anciens et fiscalité personnelle/IS proposé.',limits=['Distinguer l’extinction économique de la seule cohorte initiale et la présence formelle de textes régissant encore des opérations ou contentieux anciens.'])
add(87,'mixed_active_repealed_and_frozen_references',
    'L’article regroupe plusieurs mesures différentes ; seule une analyse par composante évite de supprimer des régimes exonératoires entiers ou de manquer un renvoi à une rédaction figée.',('1466 A','12','13','14'),parts=[
        {'part':'I','status':'frozen_reference_survives','target':'CGI1466AIquinquiesA','note':'I quater formellement abrogé avec la TP, mais le I quinquies A courant applique les alinéas 9–11 du I quater dans sa rédaction au 31 décembre 2009. Le onzième alinéa reprend l’anti-transfert incluant I quater introduit par SRU, enrichi ensuite. Une abrogation du seul numéro I quater ne purge pas ce renvoi figé.'},
        {'part':'II1°','status':'removed_after_2003_08_02','target':'loi96-987article12III','note':'Clause à 50 % pour salarié déjà présent dans l’entreprise : dernière version la contenant expire au 2 août 2003. Elle n’est plus dans l’article courant.'},
        {'part':'II2°','status':'active_literal_descendant','target':'loi96-987article12IIIbis','note':'Perte d’exonération pour emplois transférés dans une autre ZFU et traitement des accroissements d’effectifs, toujours présents.'},
        {'part':'II3°','status':'removed_after_2002_12_31','target':'loi96-987article12IV','note':'Exclusion des embauches dans les douze mois après licenciement : dernière version la contenant expire au 31 décembre 2002.'},
        {'part':'II4°','status':'active_literal_descendant','target':'loi96-987article12VI','note':'Déclarations annuelles de main-d’œuvre/chaque embauche et suspension de l’exonération, encore présentes.'},
        {'part':'III1°et2°','status':'active_and_extended_minimum_hours','target':'loi96-987article13','note':'Durée minimale au contrat insérée dans les deux ratios de résidents ; reprise dans les cohortes ultérieures, seuils de résidents ensuite modifiés. Ne pas supprimer tout le quota de résidence comme simple retrait des mots sur les heures.'},
        {'part':'IV','status':'active_literal_descendant','target':'loi96-987article14Ialinéa2','note':'Cessation de l’exonération maladie-maternité en cas de transfert d’activité vers une autre ZFU ; les durées et cohortes ultérieures importent les conditions du I.'}],action='Candidats ciblés seulement sur les contraintes issues de SRU encore opératoires ; transitions des exonérations déjà acquises et traitement du renvoi fiscal figé nécessaires. Les suppressions de 2002/2003 ne doivent pas être comptées comme réécritures nouvelles.')
add(88,'active_autonomous_sru_article',
    'Le fonds de revitalisation économique demeure institué directement par SRU 88 ; depuis le 1er janvier 2015 son territoire est QPV et autres territoires prioritaires des contrats de ville à titre dérogatoire. Ce n’est pas un simple article modificatif épuisé.',('88',),action='Candidat entier dans collectivites-companions/002/manifest.json : abrogation prospective du fonds spécial, aides/conventions/créances antérieures protégées. Pas de réécriture autonome d’un code supposé.',limits=['La présence légale du fonds ne prouve ni activité opérationnelle ni crédits budgétaires actuels. Un décret d’application est mentionné ; son état doit être établi avant d’affirmer une purge réglementaire exhaustive.'])
add(89,'active_autonomous_sru_article',
    'La norme autonome sur les sociétés d’investissement régional reste à SRU 89 : objet, concours régionaux, formes d’intervention, représentation, tiers minimal du capital/voix, rapport annuel. L’ancienne métadonnée cite CGI 217 quaterdecies issu de SRU90, mais ce support est abrogé depuis le 1er janvier 2014 (loi2013-1278 article26, LEGIARTI000022328038) : citation historique sans avantage fiscal courant à réécrire.',('89',),action='Candidat entier dans collectivites-companions/002/manifest.json : abrogation du régime spécial, sans dissolution automatique des sociétés ni annulation des participations/statuts/conventions antérieurs. L’ancien CGI 217 quaterdecies est déjà abrogé depuis 2014 ; source historique vérifiée dans sir-supporting-source.json, agent du 90 prévenu.',limits=['Les compétences générales d’investissement régional, notamment CGCT L4211-1 8°/8°bis, ne sont pas des descendants de SRU 89 par simple similitude de nom et ne doivent pas être supprimées en bloc.'])
add(91,'negative_modification_executed',
    'SRU 91 a supprimé l’ancien troisième alinéa du I de CGI1466 A : actualisation au moins quinquennale de la liste ZUS et avis du Conseil national des villes. Cette suppression a produit son effet en 2000 ; le régime de quartiers a ensuite été refondu, notamment en 2014. Il ne subsiste pas une obligation SRU positive à couper dans le I actuel.',('1466 A',),action='Ne pas réintroduire l’ancien troisième alinéa ni remettre l’ancienne liste ZUS en vigueur. La seule abrogation de la disposition modificatrice ne fait pas revivre un texte antérieur.')

assert len(entries)==21
result={'title':'Cartographie de filiation — SRU 56–71, 86–89 et91','as_of':'2026-10-18','status':'read_only_lineage_map_not_a_draft_count','entries':entries,'evidence':{'initial_articles':str(B/'runtime/sru-integral/original-articles.json'),'canonical_full_sources':str(H/'full-law-canonical-evidence.json'),'outside_full_sources':str(H/'full-law-outside-evidence.json'),'outside_archives_replayed':467},'limits':['Cartographie de 21 articles, pas table complète des 209 articles SRU.','Les sources intégrales sont conservées ; les états, filiations, dispositions ciblées et références actuelles sont distincts des propositions.','Aucune entrée de cartographie, source historique ou mesure déjà abrogée ne compte comme article réécrit.','Les textes réglementaires hors cibles vérifiées ne sont pas déclarés intégralement purgés.']}
(H/'full-law-map.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
lines=['# Concordance — 21 articles SRU','', 'Lecture seule : aucune ligne de cette carte ne compte comme proposition réécrite. Sources initiales entières et empreintes, références actuelles et limites détaillées dans full-law-map.json.','']
for a in entries:
    lines += ['## Article '+a['sru_article']+' — '+a['status'],'',a['lineage'],'']
    for c in a['components']:lines += ['- '+c['part']+' : '+c['status']+' — '+c.get('target','')+'. '+c.get('note','')]
    lines += ['',a['drafting_action'],'']
    for r in a['current_references']:lines += ['Source : ['+r['number']+' — '+r['source_id']+']('+r['source_url']+'), version '+r['valid_from']+'.']
    for limit in a['limits']:lines += ['Limite : '+limit]
    lines += ['']
(H/'full-law-map.md').write_text('\n'.join(lines))
print('MAPPED',len(entries))
